import{_ as o,a as t,b as i}from"./chunks/b4ba66242a96ee46f263.Bu5Xdql_.js";import{_ as a,o as n,c as r,a6 as s}from"./chunks/framework.CnPv4DE1.js";const c=JSON.parse('{"title":"How To Reset Your Life In 7 Days","description":"","frontmatter":{"title":"How To Reset Your Life In 7 Days","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-to-reset-your-life-in-7-days.md","filePath":"en/letters/how-to-reset-your-life-in-7-days.md"}'),l={name:"en/letters/how-to-reset-your-life-in-7-days.md"};function u(h,e,p,d,f,y){return n(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="how-to-reset-your-life-in-7-days" tabindex="-1">How To Reset Your Life In 7 Days <a class="header-anchor" href="#how-to-reset-your-life-in-7-days" aria-label="Permalink to &quot;How To Reset Your Life In 7 Days&quot;">​</a></h1><p>Dan Koe · 2024-01-05 · <a href="https://thedankoe.com/letters/how-to-reset-your-life-in-7-days/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-to-reset-your-life-in-7-days">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/wXcEtxlrPMA?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>2 months ago, I wrote this in my notes.</p><p>I write occasional letters to myself as an awareness practice.</p><p>(This is edited a bit to flow in the newsletter):</p><blockquote><p>I can’t find joy in life anymore.</p><p>It’s not the same.</p><p>Remember when you used to go on long walks while reading or listening to lectures, audiobooks, or podcasts and your mind would light up with ideas?</p><p>You couldn’t stop writing. Everything felt seamless. That period was like a blur. A 6 month flow state. You built 3 products, gained millions of readers, and even wrote a book.</p><p>If you had to do it all over again right now, could you do it just as well?</p><p>No way.</p><p>What did your days look like?</p><p>I would wake up, go down to the lake for a walk, sit on a bench in front of that pond, read a book and highlight it nonstop.</p><p>Then, I’d go back home, take a shower, walk 10 minutes to the coffee shop, and write for 2 hours. Those 2 hours every morning built the entirety of your life right now.</p><p>Then, I’d go home again, eat breakfast (you were experimenting with different diets, maybe that’s a clue due to the novelty and dopamine from experimentation), and go out on another walk.</p><p>A little after noon, I’d go to the gym, eat afterward, learn on YouTube a bit, and then go on yet another walk.</p><p>You’d close the day out catching up with friends, maybe working a bit more, and watching a show.</p></blockquote><p>It’s been bugging me too long.</p><p>I knew that there was a way to get back to that higher state of mind – not necessarily the lifestyle itself.</p><p>I’m not one to complain though (even though that letter-to-self sounds sappy) I like to fix my problems before sharing the solution with you.</p><p>If you’re anything like me, you’ve noticed that these low periods of life are cyclical.</p><p>For a few months you feel on top of the world. You can’t stop making progress.</p><p>Then, the next few months slow down. You feel good, but things aren’t the same.</p><p>Last, you hit a wall. Your vision is exhausted. You feel lost. Negative thoughts begin to flood your mind – they can cloud your mind and prevent you from collecting hints at your next purpose in life that sends you down a rabbit hole of obsession.</p><p>This letter is for those in that final phase.</p><p>The ones that can’t find the same zest for life that they used to.</p><p>The ones that can’t find joy in reading a book or walking in nature.</p><p>2 notes before we start:</p><ol><li>My book, The Art Of Focus, goes live on January 16th. You can <a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">preorder the Kindle or Audible version now</a> or wait for the paperback on that date (mark your calendars).</li><li><a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> – a college level experience for the creator economy – is open for enrollment. Start your digital career in 90 days by turning your worldview, interests, and expertise into a flexible online career.</li></ol><h2 id="your-mind-is-a-supercomputer-running-the-game-of-life" tabindex="-1">Your Mind Is A Supercomputer Running The Game Of Life <a class="header-anchor" href="#your-mind-is-a-supercomputer-running-the-game-of-life" aria-label="Permalink to &quot;Your Mind Is A Supercomputer Running The Game Of Life&quot;">​</a></h2><blockquote><p>When our mind is not engaged with being or doing, we allow random thoughts to register in our awareness. “Random” in this case does not mean half good thoughts and half bad thoughts. For every one good thought, there are a hundred bad ones. – The Art Of Focus</p></blockquote><p>I want you to think of your mind as a supercomputer.</p><p>Your ability to process information is dependent on a few things, but I want to bring attention to your RAM.</p><p>RAM — or “random access memory” — is one of the most important parts of a computer, it determines performance.</p><p>The more RAM you use up with different programs running, open browser tabs, and the performance requirements of what you have running, the slower your performance will be.</p><p>This is no different from your focus, what you hold in your conscious attention.</p><p>Humans can process 10-50 bits of information per second. That adds up to 125 billion bits of information in your lifetime.</p><p>Most people live with multiple high-demand programs running that are draining the limited creative energy they have.</p><ul><li>Thoughts about regretful past mistakes</li><li>Thoughts about stressful future happenings</li><li>Desires of hunger and entertainment to escape those thoughts</li><li>An internal cry to break out of their conditioned way of living</li><li>A list of mixed-priority tasks that need to be finished</li><li>Open loops of tasks they were supposed to complete but forgot about</li></ul><p>The list goes on and on.</p><p>The modern mind has its attention split in infinite directions by default. We go about our lives stressed and near sickness. Rather than living in the present with singular focus on a vision for the future and a worry-free mind, we are the opposite. Living in a false reality created by split attention.</p><p>When we hold too much of the past or future in the contents of our consciousness, chaos ensues. The mind tends toward disorder. If not kept in check, we lose the sense of control over our lives that leads to enjoyment. This is accomplished through controlled consciousness.</p><p>Singular focus creates clarity. Fragmented focus creates tension. Tension allows stress to sneak in. Stress is the enemy of creativity.</p><h3 id="how-to-win-the-game-of-life" tabindex="-1">How To Win The Game Of Life <a class="header-anchor" href="#how-to-win-the-game-of-life" aria-label="Permalink to &quot;How To Win The Game Of Life&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>Let’s imagine the 125 billion bits of information you can process in your lifetime as your <em>life’s potential.</em></p><p>Now, let’s think of your mind as the digestive system of reality.</p><p>If you “eat” too much information, you get anxious.</p><p>If you “eat” too little information, you get bored.</p><p>To maximize life enjoyment, maximize the amount of time you spend at your edge.</p><p>You win the game of life by finding enjoyment, not pleasure (big difference), in as much of your experience as possible. Your experience is the present moment.</p><p>“Winning” the game of life isn’t an outcome but a process.</p><p>You are either winning right now, regardless of your emotional state or status in the social hierarchy, or you are losing by projecting out of the present moment.</p><p>In bodybuilding, the optimal amount of nutrition to fuel muscle growth is just above maintenance. If you eat too much, you feel groggy. If you eat too little, you don’t have enough energy to push hard.</p><p>In mindbuilding, you must learn and build in unison. Metabolize your experience with daily practice. You don’t know where to go next because you haven’t exposed yourself to the information that acts as a feint light in the unknown.</p><p>In life, you must push into the unknown to fuel your mind.</p><p>Expose yourself to new information and experience (<strong>curiosity</strong>).</p><p>Create something of value with that information to digest it (<strong>passion</strong>).</p><p>Expand your mind when that experience becomes a part of you with practice (<strong>mastery</strong>).</p><p>Transcend that phase of life by passing down that value to others (<strong>connection</strong>).</p><p><strong>That’s the recipe for the good life:</strong></p><p>Create, expand, and transcend with the experience you acquire by pursuing self-generated goals that lead you into the unknown.</p><h3 id="creating-your-own-game-or-reality" tabindex="-1">Creating Your Own Game (Or Reality) <a class="header-anchor" href="#creating-your-own-game-or-reality" aria-label="Permalink to &quot;Creating Your Own Game (Or Reality)&quot;">​</a></h3><p>Everyone has played a game that they are completely immersed in.</p><p>They forget everything else, enter the flow state, and may not realize that they are in peak experience – the beautiful spot where new information is digested as reality flows through them.</p><p>When you start playing a game, you go through a tutorial phase that introduces you to the rules, goals, and skills required to play the game well.</p><p>Games are a hierarchy of goals:</p><ul><li>How to win</li><li>How to progress to each sub-goal of winning</li><li>Upgrading your character to continue progressing</li></ul><p>Every level of the game requires a certain level of skill to match the challenge of that level.</p><p>If you are an absolute beginner, you have no business challenging a higher level. You will lose in that moment and probably quit.</p><p>You have to go through the same progression as everyone else.</p><p>You must learn, fail, practice, get better, and expand your knowledge of the game as you progress.</p><p>In life, it’s no different.</p><p>So, to get immersed in the game of your own life, you must first create it.</p><h2 id="how-to-reset-your-life-in-7-days-1" tabindex="-1">How To Reset Your Life In 7 Days <a class="header-anchor" href="#how-to-reset-your-life-in-7-days-1" aria-label="Permalink to &quot;How To Reset Your Life In 7 Days&quot;">​</a></h2><p>This is a process I run through when life gets a bit too messy.</p><p>Like when you’re constantly thinking back to a time when “life was better.”</p><p>Or when your routines fall apart and all of these little tasks pop up that drain all of your time in the day.</p><p>We are going to run through this process fast… please put it to use.</p><p>Here’s how you reset your life in 7 days:</p><h3 id="_1-take-note-of-how-you-feel" tabindex="-1">1) Take Note Of How You Feel <a class="header-anchor" href="#_1-take-note-of-how-you-feel" aria-label="Permalink to &quot;1) Take Note Of How You Feel&quot;">​</a></h3><p>Pull out a notebook and write down:</p><ul><li>Exactly what you are doing on a daily basis.</li><li>How you feel morning, afternoon, and night.</li></ul><p>Take 10 minutes and get specific.</p><p>This is important for identifying unconscious parasites (time and energy suckers).</p><p>I do all of this in the quarterly section of <a href="https://thedankoe.com/planner" target="_blank" rel="noreferrer">The FOCI Planner</a>.</p><h3 id="_2-get-clear-on-what-you-want" tabindex="-1">2) Get Clear On What You Want <a class="header-anchor" href="#_2-get-clear-on-what-you-want" aria-label="Permalink to &quot;2) Get Clear On What You Want&quot;">​</a></h3><p><img src="'+t+'" alt=""></p><p><em>You have to realize what you don’t want to figure out what you want – even if it is destructive – to realize what you don’t want. Preventing yourself from making mistakes is the stupidest mistake of all.</em></p><p>It is impossible to know with absolute certainty what is going to happen in the future.</p><p>This is why the masses flock to “secure” jobs and belief systems.</p><p>It’s an illusion of certainty to avoid struggle. You can’t skip making mistakes. Mistakes are your light in the dark.</p><p>Start with a minimum viable vision.</p><ul><li>What do you want your life to look like?</li><li>What do you want your mind to look like?</li><li>What do you want your body to look like?</li></ul><p><em>Get specific and write down every detail for your future.</em></p><p>Now, break it down into goals.</p><p>Not for achievement, but for clarity.</p><p>Yearly goals and monthly goals.</p><p>You need direction for your life. Goals are a filter for skills to learn and opportunities to register.</p><p>Your day-to-day experience must be perceived through your vision as the game you are trying to win.</p><h3 id="_3-prioritize-remove-restructure-your-days" tabindex="-1">3) Prioritize, Remove, &amp; Restructure Your Days <a class="header-anchor" href="#_3-prioritize-remove-restructure-your-days" aria-label="Permalink to &quot;3) Prioritize, Remove, &amp; Restructure Your Days&quot;">​</a></h3><p>The reason you aren’t getting the results you used to is because:</p><ul><li>You feel pressed for time</li><li>You don’t have the energy to get results</li><li><em>You stopped doing the things that got results</em></li></ul><p>Look over your brain dump from above.</p><p>What can you change?</p><p>Prioritize the things that will get results.</p><p>Remove the things that snuck their way into your day (and don’t deserve to be there).</p><p>Restructure specific tasks and obligations to free up more time.</p><p>Get the chaotic structure of your mind on paper and reorganize it.</p><h3 id="_4-cornerstone-habits-of-the-good-life" tabindex="-1">4) Cornerstone Habits Of The Good Life <a class="header-anchor" href="#_4-cornerstone-habits-of-the-good-life" aria-label="Permalink to &quot;4) Cornerstone Habits Of The Good Life&quot;">​</a></h3><p><img src="'+i+'" alt=""></p><p>You now have direction (goals) and awareness of why you aren’t achieving them (anti-goals).</p><p>Now, you need to cultivate 2 habits to bridge the gap:</p><ol><li><strong>Learning</strong> – for novel information to fuel your skill acquisition and knowledge.</li><li><strong>Building</strong> – to metabolize the information and build mental muscle.</li></ol><p>Both are expensive dopamine.</p><p>Start with 30 minutes of each a day.</p><p>30 minutes of self-education in the morning.</p><p>30 minutes of building a project that will contribute to your vision.</p><p>If you can’t set aside 1 hour each morning, when distractions are minimal, to build your future – go back to step 3 and get your priorities straight.</p><p>If you want, you can learn the high-value skill of digital writing with my course, <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>, to build a future in the new economy.</p><h3 id="_5-create-a-week-long-plan" tabindex="-1">5) Create A Week Long Plan <a class="header-anchor" href="#_5-create-a-week-long-plan" aria-label="Permalink to &quot;5) Create A Week Long Plan&quot;">​</a></h3><p>You are in this chaotic spot in life because of entropy.</p><p>The organization of your life (and therefore the mind) tends toward disorder if you don’t perform mental housekeeping.</p><p>This is dangerous because you can pick up bad habits along the way.</p><p>Habits are difficult to break.</p><p>But you can make the process easier with clarity.</p><p>Take 10 minutes.</p><p>Write out every single thing you are going to do for the next week.</p><p>This shouldn’t sound crazy or difficult.</p><p>This is how you reduce the friction of making better decisions.</p><p>Write out:</p><ul><li>Your morning routine</li><li>Your focused work routine</li><li>Other tasks and meetings</li><li>Nightly routine</li></ul><p>The hardest part is not giving attention to the negative thoughts that inevitably pop up when mediocre habits are threatened. Mindfulness is your friend for starting your new plan.</p><p>You will have to experiment as you go.</p><p>If the routine doesn’t flow, go back to your notebook and write what you’re going to do the next day.</p><p>This is how you create a system for your life.</p><p>You create a system for your life by mapping out your week, sticking to the plan, identifying problems, experimenting with solutions, and repeating the process until you reach your ideal future.</p><p>It gets more efficient with time if you make this ‘mental housekeeping’ a regular practice.</p><p>Before you know it, new skills will become second nature and you will be baffled by how far you’ve come.</p>',129)])])}const w=a(l,[["render",u]]);export{c as __pageData,w as default};
